230: ```motoko filepath=src/backend/mixins/gmail-messaging.mo
231: import Map "mo:core/Map";
232: import Principal "mo:core/Principal";
233: import Runtime "mo:core/Runtime";
234: import LibGmail "../lib/gmail";
235: 
236: mixin (
237:   gmailConfig : { var clientId : Text; var clientSecret : Text },
238:   gmailConnections : Map.Map<Principal, LibGmail.GmailConnection>,
239:   pendingGmailFlows : Map.Map<Principal, LibGmail.PendingOAuth>,
240: ) {
241:   public query ({ caller }) func isMyGmailConnected() : async Bool {
242:     Map.containsKey(gmailConnections, Principal.compare, caller);
243:   };
244: 
245:   public query ({ caller }) func getMyGmailEmailAddress() : async ?Text {
246:     if (caller.isAnonymous()) {
247:       Runtime.trap("Sign in to view your connected Gmail address");
248:     };
249:     switch (Map.get(gmailConnections, Principal.compare, caller)) {
250:       case (?connection) ?connection.emailAddress;
251:       case null null;
252:     };
253:   };
254: 
255:   public shared ({ caller }) func startGmailOAuth(redirectUri : Text) : async Text {
256:     if (caller.isAnonymous()) {
257:       Runtime.trap("Sign in to connect Gmail");
258:     };
259:     if (gmailConfig.clientId.size() == 0) {
260:       Runtime.trap("Gmail is not configured (admin must set credentials)");
261:     };
262:     await* LibGmail.startAuthorize(
263:       gmailConfig.clientId, redirectUri, caller, pendingGmailFlows,
264:     );
265:   };
266: 
267:   public shared ({ caller }) func completeGmailOAuth(code : Text, state : Text) : async () {
268:     if (caller.isAnonymous()) {
269:       Runtime.trap("Sign in to connect Gmail");
270:     };
271:     if (gmailConfig.clientId.size() == 0) {
272:       Runtime.trap("Gmail is not configured");
273:     };
274:     let ?pending = Map.get(pendingGmailFlows, Principal.compare, caller) else {
275:       Runtime.trap("No pending OAuth flow — call startGmailOAuth first");
276:     };
277:     if (state != pending.state) {
278:       Runtime.trap("OAuth state did not match the pending Gmail flow");
279:     };
280:     Map.remove(pendingGmailFlows, Principal.compare, caller);
281:     let connection = await* LibGmail.exchangeCode(
282:       gmailConfig.clientId, gmailConfig.clientSecret, code,
283:       pending.redirectUri, pending.codeVerifier,
284:     );
285:     Map.add(gmailConnections, Principal.compare, caller, connection);
286:   };
287: 
288:   public shared ({ caller }) func sendEmail(
289:     to : Text, subject : Text, body : Text,
290:   ) : async Text {
291:     if (caller.isAnonymous()) {
292:       Runtime.trap("Sign in to send email");
293:     };
294:     let ?connection = Map.get(gmailConnections, Principal.compare, caller) else {
295:       Runtime.trap("Connect your Gmail account first");
296:     };
297:     await* LibGmail.sendEmail(
298:       gmailConfig.clientId, gmailConfig.clientSecret, connection, caller,
299:       gmailConnections, to, subject, body,
300:     );
301:   };
302: 
303:   public shared ({ caller }) func disconnectMyGmail() : async () {
304:     if (caller.isAnonymous()) {
305:       Runtime.trap("Sign in to disconnect");
306:     };
307:     Map.remove(gmailConnections, Principal.compare, caller);
308:   };
309: };
310: ```
